package spectrogram

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/tphakala/birdnet-go/internal/conf"
	"github.com/tphakala/birdnet-go/internal/logger"
	"github.com/tphakala/birdnet-go/internal/securefs"
)

const (
	// benchClipDirEnv names the directory that holds the benchmark clips. The
	// benchmark skips when it is unset, so the long clips are neither part of the
	// repository nor generated by the benchmark.
	benchClipDirEnv = "BIRDNET_BENCH_CLIP_DIR"

	// benchWidth is the raster width the native render benchmark draws at.
	benchWidth = 1026
)

// benchClipLengths are the clip lengths the benchmark reads, in the name each
// clip file carries.
var benchClipLengths = []string{"30s", "20min"}

// benchClipFormats are the file extensions of the formats the benchmark reads.
var benchClipFormats = []string{"wav", "flac", "mp3", "m4a", "opus"}

// BenchmarkNativeGenerateFromFile times GenerateFromFile with the native
// renderer on clips named clip_<length>.<format> in the directory named by
// BIRDNET_BENCH_CLIP_DIR, for example clip_20min.flac. A missing clip skips its
// sub-benchmark. To compare memory, run one format per process with a small
// -benchtime and -cpu 1 and read the peak resident size from the operating
// system, for example `/usr/bin/time -l` on the built test binary, since the Go
// benchmark output carries only allocation counts.
func BenchmarkNativeGenerateFromFile(b *testing.B) {
	dir := os.Getenv(benchClipDirEnv)
	if dir == "" {
		b.Skipf("%s is not set", benchClipDirEnv)
	}

	for _, length := range benchClipLengths {
		for _, format := range benchClipFormats {
			clip := filepath.Join(dir, "clip_"+length+"."+format)
			b.Run(format+"_"+length, func(b *testing.B) {
				if _, err := os.Stat(clip); err != nil {
					b.Skipf("no clip: %v", err)
				}
				outDir := b.TempDir()
				sfs, err := securefs.New(outDir)
				require.NoError(b, err)
				b.Cleanup(func() { _ = sfs.Close() })
				gen := NewGenerator(&conf.Settings{}, sfs, logger.Global().Module("spectrogram.bench"))
				out := filepath.Join(outDir, "out.png")

				b.ReportAllocs()
				for b.Loop() {
					require.NoError(b, gen.GenerateFromFile(b.Context(), clip, out, benchWidth, false))
				}
			})
		}
	}
}
